const metadata=await(await fetch('../figure-review.json')).json(),select=document.getElementById('figure'),image=document.getElementById('source'),viewport=document.getElementById('viewport'),notice=document.getElementById('notice');let scale=1,x=0,y=0,generation=0,drag=null;for(const f of metadata.figures){const o=document.createElement('option');o.value=f.id;o.textContent=f.id+'. '+f.title;select.append(o);}function draw(){image.style.transform=`translate(${x}px,${y}px) scale(${scale})`;const full=x>=-.5&&y>=-.5&&x+image.naturalWidth*scale<=viewport.clientWidth+.5&&y+image.naturalHeight*scale<=viewport.clientHeight+.5;notice.textContent=full?'Entire source figure visible.':'Magnified or panned view: source figure may be cropped. Use Fit entire figure to restore context.';viewport.dataset.state=JSON.stringify({scale,x,y,full,naturalWidth:image.naturalWidth,naturalHeight:image.naturalHeight});}function fit(){scale=Math.min(viewport.clientWidth/image.naturalWidth,viewport.clientHeight/image.naturalHeight);x=(viewport.clientWidth-image.naturalWidth*scale)/2;y=(viewport.clientHeight-image.naturalHeight*scale)/2;draw();}function scaleTo(value){const next=Math.min(8,Math.max(.05,value)),cx=viewport.clientWidth/2,cy=viewport.clientHeight/2;x=cx+(x-cx)*next/scale;y=cy+(y-cy)*next/scale;scale=next;draw();}function zoom(factor){scaleTo(scale*factor);}let objectURL=null;
async function load(){
 const ticket=++generation,f=metadata.figures.find(r=>String(r.id)===select.value);
 delete document.body.dataset.ready;image.style.visibility='hidden';notice.textContent='Loading verified source image…';
 const controls=['fit','native','in','out'];for(const id of controls)document.getElementById(id).disabled=true;
 document.getElementById('caption').textContent=f.originalCaption;document.getElementById('meaning').textContent=f.laterality;document.getElementById('discrepancy').textContent=f.captionDiscrepancy||'';
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);let pendingURL=null;
 try{
  const response=await fetch('../'+f.file,{signal:controller.signal,credentials:'same-origin'});if(response.status!==200)throw Error('Source returned HTTP '+response.status);
  const reader=response.body.getReader(),chunks=[];let length=0;
  try{while(true){const {value,done}=await reader.read();if(done)break;length+=value.length;if(length>f.bytes)throw Error('Source response exceeds recorded size');chunks.push(value);}}finally{await reader.cancel();}
  if(length!==f.bytes)throw Error('Source response is incomplete');const raw=new Uint8Array(length);let offset=0;for(const chunk of chunks){raw.set(chunk,offset);offset+=chunk.length;}
  const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',raw))].map(v=>v.toString(16).padStart(2,'0')).join('');if(hash!==f.sha256)throw Error('Source checksum differs');
  pendingURL=URL.createObjectURL(new Blob([raw],{type:f.file.endsWith('.webp')?'image/webp':'image/jpeg'}));const decoded=new Image();decoded.src=pendingURL;await decoded.decode();if(ticket!==generation)return;
  if(decoded.naturalWidth!==f.dimensions[0]||decoded.naturalHeight!==f.dimensions[1])throw Error('Source dimensions differ');
  const old=objectURL;objectURL=pendingURL;pendingURL=null;image.src=objectURL;await image.decode();if(old)URL.revokeObjectURL(old);if(ticket!==generation)return;
  image.alt=f.title+'; original source annotations retained';image.style.visibility='visible';for(const id of controls)document.getElementById(id).disabled=false;fit();document.body.dataset.ready=String(f.id);
 }catch(error){if(ticket===generation)notice.textContent='Source image unavailable: '+error.message+'. Use Retry source image.';}
 finally{clearTimeout(timer);controller.abort();if(pendingURL)URL.revokeObjectURL(pendingURL);}
}
document.getElementById('retry').onclick=load;
select.onchange=load;document.getElementById('fit').onclick=fit;document.getElementById('in').onclick=()=>zoom(1.5);document.getElementById('out').onclick=()=>zoom(1/1.5);document.getElementById('native').onclick=()=>scaleTo(1);viewport.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY};viewport.setPointerCapture(e.pointerId);};viewport.onpointermove=e=>{if(drag){x+=e.clientX-drag.x;y+=e.clientY-drag.y;drag={x:e.clientX,y:e.clientY};draw();}};viewport.onpointerup=()=>drag=null;viewport.onpointercancel=()=>drag=null;viewport.onkeydown=e=>{const d={ArrowLeft:[24,0],ArrowRight:[-24,0],ArrowUp:[0,24],ArrowDown:[0,-24]}[e.key];if(d){e.preventDefault();x+=d[0];y+=d[1];draw();}};new ResizeObserver(()=>{if(image.naturalWidth)fit();}).observe(viewport);await load();